def _check_dictation_project_context(config: Config) -> DoctorCheck:
    """Report cwd-based project detection (HS-3-02).

    Always opt-in via dictation.pipeline.enabled — when disabled,
    skips with PASS to keep `holdspeak doctor` quiet on the default
    path. Never returns FAIL: a missing project just means the
    `kb-enricher` stage has no context to inject (DIR-F-007 covers
    that path).
    """
    if not config.dictation.pipeline.enabled:
        return DoctorCheck(
            name="Project context",
            status="PASS",
            detail="off (dictation clean-up is disabled; it is optional)",
        )

    from ..plugins.dictation.project_root import detect_project_for_cwd

    try:
        project = detect_project_for_cwd()
    except Exception as exc:  # pragma: no cover — defensive
        return DoctorCheck(
            name="Project context",
            status="WARN",
            detail=f"detection raised {type(exc).__name__}: {exc}",
            fix="File a bug — `detect_project_for_cwd` should never raise on a normal cwd.",
        )

    if project is None:
        return DoctorCheck(
            name="Project context",
            status="WARN",
            detail=f"no project root detected from cwd={Path.cwd()}",
            fix=(
                "Launch holdspeak from inside a project directory, "
                "or `mkdir <project>/.holdspeak` to mark a project root."
            ),
        )

    return DoctorCheck(
        name="Project context",
        status="PASS",
        detail=(
            f"found {project['name']} at {project['root']} (marker: {project['anchor']})"
            + (" with a knowledge base" if "kb" in project else "")
        ),
    )

def _check_runtime_profiles(config: Config) -> DoctorCheck:
    """Name the assigned summary route and each enabled dictation profile.

    The summary line reads the current SERVICE route. The legacy meeting config
    pointer is deliberately not a source of truth for that route. A dangling
    dictation assignment is a WARN with the resolver's own reason; an adopted
    profile that `requires_key` with no key in the hub's env is a WARN naming
    the exact env var. Never FAIL — every fallback keeps the pipeline running.
    """
    from ..intel.providers import (
        _lookup_profile_record,
        effective_dictation_llm,
        endpoint_host,
        profile_key_env,
    )

    lines: list[str] = []
    try:
        from ..db import get_database
        from ..services.meeting_route_projection import summary_route_display

        summary_route = summary_route_display(get_database())
    except Exception:
        # Doctor must remain readable while the database is unavailable. The
        # route helper owns the detailed unavailable reason when it can run.
        summary_route = {
            "status": "unavailable",
            "reason_code": "route unavailable",
            "legs": [],
        }
    if summary_route.get("status") == "ready" and summary_route.get("legs"):
        for leg in summary_route["legs"]:
            profile_label = str(
                leg.get("profile_label") or leg.get("profile_id") or "unknown"
            )
            node = str(leg.get("node") or "").strip()
            host = str(leg.get("host") or "unavailable").strip()
            if node:
                destination = f"mesh node '{node}'"
            elif str(leg.get("boundary") or "") == "local":
                destination = "This device"
            else:
                destination = host
            lines.append(
                f"Meeting summary: profile '{profile_label}' ({destination})"
            )
    else:
        reason = str(summary_route.get("reason_code") or "route unavailable")
        lines.append(f"Meeting summary: unavailable ({reason})")
    lines.append("Live analysis is off for Record.")

    pipelines: list[tuple[str, object]] = []
    if config.dictation.pipeline.enabled:
        pipelines.append(("dictation", effective_dictation_llm(config.dictation.runtime)))
    if not pipelines:
        return DoctorCheck(
            name="Runtime profiles",
            status="PASS",
            detail="; ".join(lines + ["no dictation pipeline is enabled"]),
        )

    warns: list[str] = []
    fixes: list[str] = []
    for label, effective in pipelines:
        if effective.profile_id:
            where = (
                f"mesh node '{effective.node}'"
                if getattr(effective, "node", None)
                else (endpoint_host(effective.base_url) or effective.base_url)
            )
            lines.append(f"{label}: profile '{effective.profile_name}' ({where})")
            try:
                record = _lookup_profile_record(effective.profile_id)
            except Exception:
                record = None
            if (
                record is not None
                and bool(getattr(record, "requires_key", False))
                and not _doctor_profile_key_present(effective.api_key_env)
            ):
                warns.append(
                    f"{label}: profile '{effective.profile_name}' requires a key"
                    f" but ${effective.api_key_env} is unset"
                )
                fixes.append(
                    "Set the key in Settings → Models → [destination]. "
                    f"For a headless/service hub, export {profile_key_env(effective.profile_id)}=<key> "
                    "(keys never sync; each device holds its own)"
                )
        elif effective.reason:
            warns.append(f"{label}: {effective.reason}")
            fixes.append(
                f"Re-pick the {label} profile in Settings, or clear its profile id"
            )
        else:
            lines.append(f"{label}: hub default (no profile assigned)")

    if warns:
        return DoctorCheck(
            name="Runtime profiles",
            status="WARN",
            detail="; ".join(warns + lines),
            fix=" · ".join(dict.fromkeys(fixes)),
        )
    return DoctorCheck(
        name="Runtime profiles",
        status="PASS",
        detail="; ".join(lines),
    )

def _check_inference_targets() -> DoctorCheck:
    """HS-92-07: list named destination readiness without probing a network."""
    try:
        from ..db import get_database
        from ..inference_targets import list_inference_targets

        targets = list_inference_targets(get_database())
    except Exception as exc:
        return DoctorCheck(
            name="Where AI runs",
            status="WARN",
            detail=f"destination inventory unavailable ({exc.__class__.__name__})",
            fix="Run `holdspeak doctor` after the database is available.",
        )
    labels = {
        "this_device": "this device",
        "paired_device": "paired device",
        "private_endpoint": "private endpoint",
        "mesh_node": "mesh node",
        "external_service": "external service",
        "unsupported": "unsupported destination",
    }
    # The boundary in words, never its wire value (`same_device`); a boundary
    # that says the same as the kind is said once.
    boundaries = {
        "same_device": "this device",
        "paired_device": "paired device",
        "private_network": "private network",
        "external_service": "external service",
    }

    def where(target: Any) -> str:
        kind = labels.get(target.kind, str(target.kind).replace("_", " "))
        boundary = boundaries.get(str(target.boundary), str(target.boundary).replace("_", " "))
        return kind if boundary == kind else f"{kind} · {boundary}"

    from ..inference_targets import NOT_SET_UP_REASON

    def head(target: Any) -> str:
        # PHILO-15 11 (B08): "This device: this device" said the place twice.
        place = where(target)
        return target.name if str(target.name).strip().lower() == place else f"{target.name}: {place}"

    def state(target: Any) -> str:
        if target.ready:
            return " · ready"
        if target.readiness_reason == NOT_SET_UP_REASON:
            return " · not set up yet"
        return f" · unavailable ({target.readiness_reason})"

    unavailable = [target for target in targets if not target.ready]
    lines = [f"{head(target)}{state(target)}" for target in targets]
    only_not_set_up = bool(unavailable) and all(
        target.readiness_reason == NOT_SET_UP_REASON for target in unavailable
    )
    return DoctorCheck(
        name="Where AI runs",
        status="WARN" if unavailable else "PASS",
        detail="; ".join(lines),
        fix=(
            None if not unavailable
            else SET_UP_LOCAL_AI if only_not_set_up
            else "Open Settings > Models and choose a place that is ready, or fix the key, device or address it names."
        ),
    )

def _check_mesh_edges(config: Config) -> DoctorCheck:
    """HS-85-04: which mesh edges are alive right now.

    Liveness is born from each worker's claim polling — this reports every
    node that has EVER served, with its age, and flags nothing by itself
    (an offline edge only matters when a profile points at it, which the
    "Runtime profiles" check owns). Informational, always cheap.
    """

    from ..intel.mesh_relay import DEFAULT_LIVENESS_WINDOW_SECONDS

    try:
        from ..db import get_database

        workers = get_database().mesh_relay.list_workers()
    except Exception as exc:
        return DoctorCheck(
            name="Other devices",
            status="PASS",
            detail=f"not readable ({exc.__class__.__name__}) — no mesh serving on this hub",
        )
    if not workers:
        return DoctorCheck(
            name="Other devices",
            status="PASS",
            detail="no other device runs AI for this desk (to add one: `holdspeak mesh serve` on that device)",
        )
    now = local_wall()
    parts: list[str] = []
    for node, last_seen in sorted(workers.items()):
        age = int((now - last_seen).total_seconds())
        state = "live" if age <= DEFAULT_LIVENESS_WINDOW_SECONDS else "offline"
        parts.append(f"{node}: {state} ({age}s ago)")
    return DoctorCheck(name="Other devices", status="PASS", detail="; ".join(parts))

def _check_dictation_constraint_compile(config: Config) -> DoctorCheck:
    """DIR-DOC-002: compile the loaded `blocks.yaml` against the active backend.

    Pure-Python compile (cheap), so the doctor runs it eagerly. Never
    returns `FAIL` per DIR-DOC-003.
    """
    cfg = config.dictation
    if not cfg.pipeline.enabled:
        return DoctorCheck(
            name="Dictation blocks",
            status="PASS",
            detail="off (dictation clean-up is disabled; it is optional)",
        )

    from ..plugins.dictation.assembly import DEFAULT_GLOBAL_BLOCKS_PATH
    from ..plugins.dictation.blocks import BlockConfigError, resolve_blocks
    from ..plugins.dictation.grammars import (
        GrammarCompileError,
        StructuredOutputSchema,
        to_gbnf,
        to_outlines,
    )
    from ..plugins.dictation.runtime import RuntimeUnavailableError, resolve_backend

    try:
        loaded = resolve_blocks(DEFAULT_GLOBAL_BLOCKS_PATH, None)
    except BlockConfigError as exc:
        return DoctorCheck(
            name="Dictation blocks",
            status="WARN",
            detail=f"blocks.yaml failed to load: {exc}",
            fix="Run `holdspeak dictation blocks validate` for the full error.",
        )

    if not loaded.blocks:
        return DoctorCheck(
            name="Dictation blocks",
            status="PASS",
            detail="no dictation blocks yet; nothing to check",
        )

    try:
        resolved, _reason = resolve_backend(
            cfg.runtime.backend, mlx_model_set=bool(str(cfg.runtime.mlx_model or "").strip())
        )
    except RuntimeUnavailableError:
        # The runtime check already reported this; reporting again
        # would be noise. Compile against both shapes so block
        # authors still get a "your YAML is structurally valid"
        # signal.
        resolved = "llama_cpp"

    try:
        block_set = loaded.to_block_set()
        schema = StructuredOutputSchema.from_block_set(block_set)
        if resolved in {"mlx", "openai_compatible"}:
            to_outlines(schema)
        else:
            to_gbnf(schema)
    except (GrammarCompileError, Exception) as exc:
        return DoctorCheck(
            name="Dictation blocks",
            status="WARN",
            detail=f"{resolved} compile failed: {type(exc).__name__}: {exc}",
            fix="Run `holdspeak dictation blocks validate` to see the offending block.",
        )

    return DoctorCheck(
        name="Dictation blocks",
        status="PASS",
        detail=f"{len(loaded.blocks)} block(s) are correct ({resolved})",
    )

def _check_dictation_runtime_counters(config: Config) -> DoctorCheck:
    """DIR-O-002: surface the four LLM-runtime counters (HS-3-04).

    Always PASS — counters are advisory observability, not a health
    signal. Skipped with PASS when the dictation pipeline is disabled
    so the default doctor output stays quiet.
    """
    if not config.dictation.pipeline.enabled:
        return DoctorCheck(
            name="Dictation AI use",
            status="PASS",
            detail="off (dictation clean-up is disabled; it is optional)",
        )

    from ..plugins.dictation.runtime_counters import (
        get_counters,
        get_session_status,
    )

    counters = get_counters()
    session = get_session_status()
    detail = (
        f"{counters['model_loads']} model loads, "
        f"{counters['classify_calls']} calls, "
        f"{counters['classify_failures']} failures, "
        f"{counters['constrained_retries']} retries"
    )
    if session["llm_disabled_for_session"]:
        return DoctorCheck(
            name="Dictation AI use",
            status="WARN",
            detail=detail + f"; off for this session: {session['disabled_reason']}",
            fix="Restart `holdspeak` to retry. If it keeps tripping, raise `dictation.pipeline.max_total_latency_ms` or `warm_on_start: true`.",
        )
    return DoctorCheck(
        name="Dictation AI use",
        status="PASS",
        detail=detail,
    )

def _check_mir_routing(config: Config) -> DoctorCheck:
    """MIR-O-001 / spec §9.10: report MIR-01 routing-pipeline config posture.

    Never returns `FAIL` — the pipeline is opt-in (mirrors DIR-DOC-003).
    Validates the configured ``routing_profile`` against the pre-defined
    profile set so a typo surfaces here rather than at meeting stop.
    """
    cfg = config.meeting
    if not cfg.intent_router_enabled:
        return DoctorCheck(
            name="Meeting plugins",
            status="PASS",
            detail="off (optional; meeting.intent_router_enabled turns it on)",
        )

    try:
        from ..plugins.router import available_profiles
    except Exception as exc:
        return DoctorCheck(
            name="Meeting plugins",
            status="WARN",
            detail=f"router import failed: {type(exc).__name__}: {exc}",
            fix="Inspect holdspeak/plugins/router.py for import errors.",
        )

    profiles = list(available_profiles())
    # HS-130-05 / HS-134-08: doctor reports the ONE routing profile the
    # runtime reads (`effective_routing_profile`).
    from ..config.meeting import effective_routing_profile

    routing_profile = effective_routing_profile(cfg)
    if routing_profile not in profiles:
        return DoctorCheck(
            name="Meeting plugins",
            status="WARN",
            detail=(
                f"routing_profile={routing_profile!r} not in available profiles "
                f"({', '.join(profiles)})"
            ),
            fix=(
                "Set meeting.routing_profile to one of the available profiles "
                "in your config.json."
            ),
        )

    return DoctorCheck(
        name="Meeting plugins",
        status="PASS",
        detail=(
            f"enabled; profile={routing_profile}, "
